package com.opsflow.platform.domain;

import java.security.SecureRandom;
import java.time.Clock;
import java.time.Instant;
import java.util.UUID;

/**
 * Generates time-ordered UUIDv7 identifiers (RFC 9562).
 *
 * <p>Primary keys are generated by the application rather than the database, so an aggregate has
 * its identity before it is persisted — which is what lets it be referenced in the same
 * transaction that creates it.
 *
 * <p>Version 7 rather than the random version 4: the leading 48 bits are a millisecond
 * timestamp, so keys are <em>time-ordered</em> and B-tree inserts stay local to the right edge of
 * the index instead of scattering across it. With random UUIDs the index fragments and its
 * working set grows towards the size of the whole index; with v7 it stays close to the recent
 * pages.
 *
 * <p>Time-ordered is not the same as strictly increasing. The remaining bits are random, so two
 * identifiers generated within the same millisecond have no defined order relative to each other.
 * That is sufficient for index locality, which is the reason for choosing v7; it is not a
 * sequence, and nothing should treat it as one.
 *
 * <p>Layout: 48-bit big-endian timestamp, 4-bit version, 12 random bits, 2-bit variant, 62
 * random bits.
 */
public final class UuidV7 {

    private static final SecureRandom RANDOM = new SecureRandom();
    private static final long VERSION_7 = 0x7L << 12;
    private static final long VARIANT_RFC_9562 = 0b10L << 62;

    private UuidV7() {}

    public static UUID generate(Clock clock) {
        return generate(Instant.now(clock));
    }

    public static UUID generate(Instant timestamp) {
        long unixMillis = timestamp.toEpochMilli();
        if (unixMillis < 0 || unixMillis > 0xFFFF_FFFF_FFFFL) {
            throw new IllegalArgumentException("Timestamp is outside the 48-bit UUIDv7 range");
        }

        long randomA = RANDOM.nextLong() & 0x0FFFL;
        long randomB = RANDOM.nextLong() & 0x3FFF_FFFF_FFFF_FFFFL;

        long mostSignificantBits = (unixMillis << 16) | VERSION_7 | randomA;
        long leastSignificantBits = VARIANT_RFC_9562 | randomB;

        return new UUID(mostSignificantBits, leastSignificantBits);
    }

    /** The millisecond timestamp encoded in a UUIDv7. Used by tests and diagnostics. */
    public static Instant timestampOf(UUID uuid) {
        if (uuid.version() != 7) {
            throw new IllegalArgumentException("Not a UUIDv7: version " + uuid.version());
        }
        return Instant.ofEpochMilli(uuid.getMostSignificantBits() >>> 16);
    }
}
